INSERT INTO default.map_hr_kpi (kpi_code, kind, kpi_name, short_label, area, definition, formula, source_system, grain, caveats, direction, value_format, display_order, measure_name, bsc_kpi_code, target_source, needs_pay, is_home_tile, status, changed_at, changed_by, change_note, is_deleted) VALUES
    ('HR_SAUDIZATION', 'kpi', 'Saudization', 'Saudization', 'Mix', 'Saudi heads divided by heads without part-time doctors, at the last closed month of the period, added over branches.', 'Saudi heads divided by headcount without part-time doctors.', 'Fusion', 'Employee, month', 'Snapshot. Same figure as the balanced scorecard (KPI 46).', 'higher', 'pct', 3, 'BSC Saudization', 'LRN_SAUDIZATION', 'fixed', 0, 1, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_TURNOVER', 'kpi', 'Turnover %', 'Turnover', 'Flow', 'Resignations (Oasis for hospitals 1 to 5, Fusion voluntary leavers for hospitals 6 to 8) divided by average headcount, scorecard rules.', 'Resignations divided by average headcount.', 'Oasis and Fusion', 'Branch, month', 'The headline turnover everywhere. Same figure as the balanced scorecard (KPI 43). The annual target is pro-rated by the months selected.', 'lower', 'pct', 5, 'BSC Turnover', 'LRN_TURNOVER', 'fixed', 0, 1, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_STAFF_COST_PER_FTE', 'kpi', 'Staff Cost per FTE', 'Staff Cost per FTE', 'Cost', 'Payroll cost in SAR divided by the average FTE of the period.', 'Payroll cost divided by average FTE.', 'Fusion payroll', 'Branch, month', 'Needs pay access: shown as Requires pay access for other users. Same measure as Payroll Cost per FTE.', 'lower', 'sar', 7, 'Payroll Cost per FTE', '', 'fixed', 1, 1, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_REVENUE_PER_FTE', 'kpi', 'Revenue per FTE', 'Revenue per FTE', 'Productivity', 'GL net revenue divided by average FTE, part-time doctors at 0.5.', 'Net revenue divided by average FTE.', 'Oasis and Fusion GL, Fusion', 'Branch, month', 'Same figure and target as the balanced scorecard (KPI 44), so the HR status equals the BSC status.', 'higher', 'sar', 8, 'BSC Revenue per FTE', 'LRN_REVENUE_PER_FTE', 'bsc', 0, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_OVERTIME_SHARE', 'kpi', 'Overtime Share %', 'Overtime Share', 'Cost', 'Overtime gross pay divided by gross pay.', 'Overtime gross pay divided by gross pay.', 'Fusion payroll', 'Branch, month', 'Needs pay access. Flow: covers the selection.', 'lower', 'pct', 9, 'Overtime Share %', '', 'fixed', 1, 1, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_SICK_LEAVE_RATE', 'kpi', 'Sick Leave Rate %', 'Sick Leave Rate', 'Absence', 'Sick days divided by month-end FTE times past calendar days, over months with a closed headcount.', 'Sick days divided by (month-end FTE times past calendar days).', 'Fusion', 'Branch, month', 'Flow: covers the selection. Planned absence in the future is not counted.', 'lower', 'pct', 10, 'Sick Leave Rate %', '', 'fixed', 0, 1, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_LEAVE_LIABILITY', 'kpi', 'Leave Liability', 'Leave Liability', 'Leave', 'Annual leave balance valued in SAR at the last closed accrual month of the selection per branch.', 'Leave balance in days times the daily salary rate.', 'Fusion', 'Employee, plan, month', 'Needs pay access. Snapshot. Balances with no salary carry no liability.', 'lower', 'sar', 11, 'Leave Liability', '', 'fixed', 1, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_VACANCY_RATE', 'kpi', 'Vacancy Rate %', 'Vacancy Rate', 'Hiring', 'Requisition openings still open at the end of the period divided by the budgeted FTE of that year.', 'Open requisition openings divided by budgeted FTE.', 'Fusion recruiting, BI budgeted FTE', 'Branch, month', 'Snapshot. Same figure as the balanced scorecard (KPI 47).', 'lower', 'pct', 12, 'BSC Vacancy Rate', 'LRN_VACANCY_RATE', 'fixed', 0, 1, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_STAFF_TO_BED', 'kpi', 'Staff to Bed', 'Staff to Bed', 'Productivity', 'Average FTE of doctors and clinical staff divided by average available inpatient beds.', 'Average clinical FTE divided by average available beds.', 'Fusion, BSC licensed beds', 'Branch, month', 'Same figure as the balanced scorecard (KPI 45).', 'on_target', 'num', 14, 'BSC Staff to Bed', 'LRN_STAFF_TO_BED', 'fixed', 0, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_CLINICAL_TO_DOCTOR', 'kpi', 'Clinical to Doctor', 'Clinical to Doctor', 'Productivity', 'Average clinical staff (nursing, paramedical and physical therapy) divided by average doctors, part-time doctors included.', 'Average clinical staff divided by average doctors.', 'Fusion', 'Branch, month', 'Same figure as the balanced scorecard (KPI 68).', 'higher', 'num', 15, 'BSC Clinical to Doctor', 'LRN_CLINICAL_TO_DOCTOR', 'fixed', 0, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_REVENUE_PER_DOCTOR', 'kpi', 'Revenue per Doctor', 'Revenue per Doctor', 'Productivity', 'GL net revenue divided by average doctors, part-time doctors included.', 'Net revenue divided by average doctors.', 'Oasis and Fusion GL, Fusion', 'Branch, month', 'Same figure as the balanced scorecard (KPI 55).', 'higher', 'sar', 16, 'BSC Revenue per Doctor', 'FIN_REVENUE_PER_DOCTOR', 'fixed', 0, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_VISITS_PER_FTE', 'kpi', 'Visits per FTE', 'Visits per FTE', 'Productivity', 'Encounters seen divided by FTE-months of linked doctors and nurses.', 'Encounters seen divided by FTE-months of linked doctors and nurses.', 'Oasis and Fusion', 'Branch, month', 'Needs pay access. Only doctors and nurses linked between Oasis and Fusion count.', 'higher', 'num', 17, 'Visits per FTE', '', 'fixed', 1, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_REVENUE_PER_PAYROLL_SAR', 'kpi', 'Revenue per Payroll SAR', 'Revenue per Payroll SAR', 'Productivity', 'Revenue divided by the payroll cost of linked doctors and nurses, a ratio of sums.', 'Revenue divided by payroll cost of linked doctors and nurses.', 'Oasis and Fusion', 'Branch, month', 'Needs pay access. Only doctors and nurses linked between Oasis and Fusion count.', 'higher', 'num', 18, 'Revenue per Payroll SAR', '', 'fixed', 1, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_M_FTE', 'metric', 'FTE', 'FTE', 'Size', 'Month-end FTE of the last closed month in the selection per branch, contingent workers excluded.', 'Sum of FTE of employees on the payroll at month end.', 'Fusion', 'Employee, month', 'Snapshot. An FTE of 0 in Fusion is replaced by 1 (see the Data quality page).', 'on_target', 'num', 19, 'FTE', '', 'none', 0, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_M_PAYROLL_COST', 'metric', 'Payroll Cost', 'Payroll Cost', 'Cost', 'Payroll cost in SAR: the sum of cost amounts, parallel-run rows already excluded.', 'Sum of payroll cost amounts.', 'Fusion payroll', 'Branch, month', 'Needs pay access.', 'lower', 'sar', 25, 'Payroll Cost', '', 'none', 1, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_M_GROSS_PAY', 'metric', 'Gross Pay', 'Gross Pay', 'Cost', 'Gross pay in SAR, parallel-run rows already excluded, open Oasis payroll included.', 'Sum of gross pay.', 'Fusion payroll', 'Branch, month', 'Needs pay access. Includes payroll that is not closed yet, so it can change.', 'lower', 'sar', 26, 'Gross Pay', '', 'none', 1, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_M_GROSS_PAY_OPEN', 'metric', 'Gross Pay (Open Payroll)', 'Gross Pay (Open Payroll)', 'Cost', 'Gross pay in SAR of payroll the branch has not closed yet.', 'Sum of gross pay of open payroll.', 'Fusion payroll', 'Branch, month', 'Needs pay access. Changes until the month is closed.', 'lower', 'sar', 27, 'Gross Pay (Open Payroll)', '', 'none', 1, 0, 'active', now64(3), 'seed', 'wording: branches include Head Office', 0),
    ('HR_M_LEAVE_BALANCE', 'metric', 'Leave Balance (days)', 'Leave Balance (days)', 'Leave', 'Leave balance in days at the last closed accrual month of the selection per branch: the latest period of each employee and plan.', 'Sum of the latest leave balance of each employee and plan.', 'Fusion', 'Employee, plan, month', 'Snapshot.', 'lower', 'days', 29, 'Leave Balance (days)', '', 'none', 1, 0, 'active', now64(3), 'seed', 'Leave Balances is pay-gated by role; wording: branches include Head Office', 0),
    ('HR_M_CURRENT_LEAVE_BALANCE', 'metric', 'Current Leave Balance (days)', 'Current Leave Balance (days)', 'Leave', 'Leave balance in days at the latest closed accrual period, whatever dates are selected.', 'Sum of the latest leave balance of each employee and plan.', 'Fusion', 'Employee, plan', 'Latest-position measure: ignores the dates selected.', 'lower', 'days', 30, 'Current Leave Balance (days)', '', 'none', 1, 0, 'active', now64(3), 'seed', 'Leave Balances is pay-gated by role', 0),
